package io.knowledgebrain.collaboration;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class SubmissionInstructionsStoreIntegrationTest {
 SubmissionStoreIntegrationTest f;SubmissionStore.Submission first;AssignmentStore.Assignment original;
 @BeforeEach void setup(){f=new SubmissionStoreIntegrationTest();f.setup();f.open();original=f.parent.store.get(f.group,f.space,f.study,f.assignment);first=f.submit(f.f.key(),0,2,"Original answer").submission();}
 SubmissionStore.Instructions get(UUID actor,boolean owner,long version){return f.store.instructions(f.group,f.space,f.study,f.assignment,first.submissionId(),actor,owner,version);}
 @Test void exactOriginalInstructionRemainsAfterMetadataAndFurtherAttempts(){
  var old=get(f.author,false,1);assertEquals(original,old.assignment());assertEquals(first.submissionId(),old.submissionId());assertEquals(1,old.submissionVersion());assertEquals(2,old.assignmentVersion());
  var changed=f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"New title <script>","Revised instructions\n다른 지시문",f.f.trace);var second=f.submit(f.f.key(),1,3,"New answer").submission();assertEquals(old,get(f.author,false,1));assertEquals(changed,get(f.f.owner,true,2).assignment());assertEquals(second.assignmentVersion(),get(f.author,false,2).assignmentVersion());assertNotEquals(get(f.author,false,1).assignment().description(),get(f.author,false,2).assignment().description());
 }
 @Test void closedAndArchivedParentsPreserveHistoricalInstructions(){var pinned=get(f.author,false,1);f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);assertEquals(pinned,get(f.f.owner,true,1));f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,3,"RETIRED",f.f.trace);f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,1,"RETIRED",f.f.trace);assertEquals(pinned,get(f.author,false,1));assertEquals("OPEN",pinned.assignment().state());}
 @Test void peersAndWrongScopeOrMissingAttemptNeverFallBackToCurrent(){f.status(404,()->get(f.f.ids.next(),false,1));f.status(404,()->get(f.author,false,2));f.status(404,()->get(f.author,false,Long.MAX_VALUE));f.status(400,()->get(f.author,false,0));f.status(400,()->get(f.author,false,-1));for(int n=0;n<5;n++){var group=f.group;var space=f.space;var study=f.study;var assignment=f.assignment;var id=first.submissionId();var other=f.f.ids.next();switch(n){case 0->group=other;case 1->space=other;case 2->study=other;case 3->assignment=other;case 4->id=other;}final var g=group;final var s=space;final var st=study;final var a=assignment;final var i=id;f.status(404,()->f.store.instructions(g,s,st,a,i,f.f.owner,true,1));}}
 @Test void fetchingHistoryDoesNotMutateAnyCurrentRevisionOrOutbox(){var assignment=f.parent.store.get(f.group,f.space,f.study,f.assignment);int assignmentEvents=f.events(f.assignment),submissionEvents=f.events(first.submissionId());int revisions=f.f.jdbc.queryForObject("SELECT count(*) FROM assignment_submission_revision WHERE submission_id=?",Integer.class,first.submissionId());for(int n=0;n<3;n++){assertEquals(original,get(f.author,false,1).assignment());assertEquals(original,get(f.f.owner,true,1).assignment());}assertEquals(assignment,f.parent.store.get(f.group,f.space,f.study,f.assignment));assertEquals(first,f.store.mine(f.group,f.space,f.study,f.assignment,f.author,true).submission());assertEquals(assignmentEvents,f.events(f.assignment));assertEquals(submissionEvents,f.events(first.submissionId()));assertEquals(revisions,f.f.jdbc.queryForObject("SELECT count(*) FROM assignment_submission_revision WHERE submission_id=?",Integer.class,first.submissionId()));assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_feedback WHERE submission_id=?",Integer.class,first.submissionId()));assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM resubmission_request WHERE submission_id=?",Integer.class,first.submissionId()));}
 @Test void historicalReadsStayPinnedWhileCurrentAnswerAndInstructionsChange()throws Exception{var pinned=get(f.author,false,1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();for(int n=0;n<20;n++)assertEquals(pinned,get(f.author,false,1));return true;});var b=pool.submit(()->{barrier.await();f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"New current instructions","Different",f.f.trace);return f.submit(f.f.key(),1,3,"Resubmitted concurrently").submission();});assertTrue(a.get(20,TimeUnit.SECONDS));assertEquals(2,b.get(20,TimeUnit.SECONDS).version());assertEquals(pinned,get(f.author,false,1));assertEquals(3,get(f.author,false,2).assignmentVersion());}}
}
